    leg: CheckInLegParty,
    now: Date,
): CheckInLegEligibility {
    const travelling = leg.seats.filter(seat => !seat.releasedAt);
    const awaiting = travelling.filter(seat => !seat.checkedInAt);
    const counts = { travelling: travelling.length, awaiting: awaiting.length };

