                                            </p>
                                        </div>

                                        <dl className="checkin-facts">
                                            <div>
                                                <dt>Flight</dt>
                                                <dd>{leg.airline} {leg.flightNumber}</dd>
                                            </div>
                                            <div>
                                                <dt>Departs</dt>
                                                <dd>{leg.departureReadable}</dd>
                                            </div>
                                            <div>
                                                <dt>Confirmation</dt>
                                                <dd>{leg.reference}</dd>
                                            </div>
                                        </dl>

                                        {/* The window is its own list so its two
                                            ends cannot be split across rows by a
                                            column count that happens to be four:
