    switch (reason) {
        case 'OPEN':
            return 'Confirm your seat to check in for this flight.';
        case 'NOT_YET_OPEN':
            return `Check-in opens ${CHECK_IN_OPENS_HOURS} hours before departure. Come back then, or set a reminder.`;
