        const inbound = await createFlight(`I${suffix}`, CHECK_IN_OPENS_HOURS + 48);
        const user = await createUser(suffix);
        const booking = await bookSeats([outbound.id, inbound.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A', '12A'] },
