    it('refuses a leg belonging to another customer', async () => {
        const suffix = `B${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const owner = await createUser(`owner${suffix}`);
        const intruder = await createUser(`intruder${suffix}`);
        const booking = await bookSeats([flight.id], owner.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const [leg] = await legsOf(booking.id);

        mockedSession.mockResolvedValue({ user: { id: intruder.id } });

        await expect(
            checkInLegAction({ bookingId: booking.id, legId: leg.id }),
        ).rejects.toThrow('Unauthorized');

        const after = await legsOf(booking.id);
        expect(after[0].seatAssignments[0].checkedInAt).toBeNull();
    });

    it('refuses a leg that does not belong to the booking it is named with', async () => {
        // The ownership check passes -- this customer does own `booking` -- so
        // only the leg-to-booking check stands between them and stamping a
        // stranger's leg.
        const suffix = `C${Date.now()}`;
        const own = await createFlight(`W${suffix}`, 5);
        const other = await createFlight(`X${suffix}`, 5);
        const user = await createUser(`own${suffix}`);
        const stranger = await createUser(`str${suffix}`);
        const booking = await bookSeats([own.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const strangerBooking = await bookSeats([other.id], stranger.id, [
            { firstName: 'Alan', seatNumbers: ['11A'] },
        ]);
        const [strangerLeg] = await legsOf(strangerBooking.id);

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        await expect(
            checkInLegAction({ bookingId: booking.id, legId: strangerLeg.id }),
        ).rejects.toThrow('Itinerary leg not found');

        const after = await legsOf(strangerBooking.id);
        expect(after[0].seatAssignments[0].checkedInAt).toBeNull();
    });

    it('refuses a flight the window has not opened for, and writes nothing', async () => {
        const suffix = `D${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, CHECK_IN_OPENS_HOURS + 12);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const [leg] = await legsOf(booking.id);

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        const result = await checkInLegAction({ bookingId: booking.id, legId: leg.id });

        // A policy answer the customer can act on, not a thrown fault.
        expect(isActionValidationFailure(result)).toBe(true);
        expect((result as { error: { message: string } }).error.message)
            .toContain(`${CHECK_IN_OPENS_HOURS} hours`);

        const after = await legsOf(booking.id);
        expect(after[0].seatAssignments[0].checkedInAt).toBeNull();
    });

    it('refuses a cancelled flight inside an otherwise open window', async () => {
        const suffix = `E${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const [leg] = await legsOf(booking.id);
        // Cancelled after the booking exists, which is the only order that can
        // happen: `FlightBookingService` refuses to sell a cancelled flight, so a
        // booking on one always predates the cancellation.
        await prisma.flight.update({
            where: { id: flight.id },
            data: { status: 'CANCELLED' },
        });

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        const result = await checkInLegAction({ bookingId: booking.id, legId: leg.id });

        expect(isActionValidationFailure(result)).toBe(true);
        const after = await legsOf(booking.id);
        expect(after[0].seatAssignments[0].checkedInAt).toBeNull();
    });

    it('leaves the first stamp alone when pressed twice', async () => {
        const suffix = `F${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const [leg] = await legsOf(booking.id);

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        await checkInLegAction({
            bookingId: booking.id,
            legId: leg.id,
            documentsConfirmed: true,
        });
        const first = (await legsOf(booking.id))[0].seatAssignments[0].checkedInAt;
        expect(first).not.toBeNull();

        // No attestation the second time: it is already on file.
        const second = await checkInLegAction({ bookingId: booking.id, legId: leg.id });

        // Success rather than a refusal, and the same instant: re-stamping would
        // claim the traveller checked in later than they did.
        expect(isActionValidationFailure(second)).toBe(false);
        const after = (await legsOf(booking.id))[0].seatAssignments[0].checkedInAt;
        expect(after?.getTime()).toBe(first?.getTime());
    });

    it('checks in the traveller still travelling when another has released a seat', async () => {
        const suffix = `G${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
            { firstName: 'Grace', seatNumbers: ['11B'] },
        ]);
        const [leg] = await legsOf(booking.id);
        const released = leg.seatAssignments[1];
        await prisma.seatAssignment.update({
            where: { id: released.id },
            data: { releasedAt: new Date() },
        });

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        const result = await checkInLegAction({
            bookingId: booking.id,
            legId: leg.id,
            documentsConfirmed: true,
        });
        expect(isActionValidationFailure(result)).toBe(false);

        const after = await prisma.seatAssignment.findMany({
            where: { legId: leg.id },
            orderBy: { seatNumber: 'asc' },
        });
        expect(after[0].checkedInAt).not.toBeNull();
        // A released seat is nobody's boarding position any more, so stamping it
        // would record a check-in for a traveller who is not on the flight.
        expect(after[1].checkedInAt).toBeNull();
    });

    it('leaves an already checked-in traveller\'s stamp alone while checking in the rest', async () => {
        // The case the whole-party idempotency test cannot reach: with one of two
        // travellers checked in, the leg is still open, so the update *does* run.
        // Without `checkedInAt: null` on it, Ada's stamp is rewritten to now --
        // recording that she checked in later than she did.
        const suffix = `J${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
            { firstName: 'Grace', seatNumbers: ['11B'] },
        ]);
        const [leg] = await legsOf(booking.id);
        const earlier = new Date(Date.now() - 3 * HOUR);
        await prisma.seatAssignment.update({
            where: { id: leg.seatAssignments[0].id },
            data: { checkedInAt: earlier },
        });

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        const result = await checkInLegAction({
            bookingId: booking.id,
            legId: leg.id,
            documentsConfirmed: true,
        });
        expect(isActionValidationFailure(result)).toBe(false);

        const after = await prisma.seatAssignment.findMany({
            where: { legId: leg.id },
            orderBy: { seatNumber: 'asc' },
        });
        expect(after[0].checkedInAt?.getTime()).toBe(earlier.getTime());
        expect(after[1].checkedInAt).not.toBeNull();
        expect(after[1].checkedInAt!.getTime()).toBeGreaterThan(earlier.getTime());
    });

    it('refuses a cancelled booking whose flight is still in the window', async () => {
        const suffix = `H${Date.now()}`;
        const flight = await createFlight(`F${suffix}`, 5);
        const user = await createUser(suffix);
        const booking = await bookSeats([flight.id], user.id, [
            { firstName: 'Ada', seatNumbers: ['11A'] },
        ]);
        const [leg] = await legsOf(booking.id);
        await prisma.booking.update({
            where: { id: booking.id },
            data: { status: 'CANCELLED' },
        });

        mockedSession.mockResolvedValue({ user: { id: user.id } });

        const result = await checkInLegAction({ bookingId: booking.id, legId: leg.id });

        expect(isActionValidationFailure(result)).toBe(true);
        expect((result as { error: { message: string } }).error.message).toContain('cancelled');
        const after = await prisma.seatAssignment.findMany({ where: { legId: leg.id } });
        expect(after.every(seat => seat.checkedInAt === null)).toBe(true);
    });
import { randomUUID } from 'crypto';
import { expect, test } from '@playwright/test';
import { loadEnvConfig } from '@next/env';
import { prisma } from '../lib/prisma';
import { airportCodesForRoute } from '../lib/airports';
import { CHECK_IN_OPENS_HOURS } from '../lib/checkInPolicy';
import FlightBookingService from '../lib/FlightBookingService';
import { createVerifiedAccount, signInWithCredentials } from './helpers/auth';
import { bookHeldFlight } from './helpers/holdBookingSeats';

loadEnvConfig(process.cwd());

/**
 * The check-in journey #77 asks for, in a browser.
 *
 * A round trip is the case worth driving: the two legs are in different states
 * at the same instant -- the outbound inside its window, the return days from
 * opening -- so a page that answered per booking rather than per leg would be
 * wrong about one of them while looking right about the other. That is exactly
 * the class of defect this application has shipped before (#137, #253), and it
 * is invisible to a one-leg fixture.
 */
const suffix = `${Date.now()}`;
const customerEmail = `checkin-customer-${suffix}@example.com`;
const strangerEmail = `checkin-stranger-${suffix}@example.com`;
// A second owner, so the scoping test does not depend on the first test having
// run: a spec whose fixture is another test's side effect fails for the wrong
// reason the moment that test is skipped or filtered out.
const otherOwnerEmail = `checkin-other-${suffix}@example.com`;
const password = 'Password123!';

const created = { flightIds: [] as number[] };

const HOUR = 60 * 60 * 1000;

test.afterAll(async () => {
    // Each spec deletes what it created: `global-setup` cannot tell this run's
    // account from a developer's, so the teardown's snapshot comparison is the
    // only thing that catches a leak and it needs this to have run (#213).
    await prisma.booking.deleteMany({
        where: { user: { email: { contains: `-${suffix}@example.com` } } },
    });
    await prisma.flight.deleteMany({ where: { id: { in: created.flightIds } } });
    await prisma.user.deleteMany({
        where: { email: { contains: `-${suffix}@example.com` } },
    });
});

async function aFlight(flightNumber: string, hoursFromNow: number, route: [string, string]) {
    const flight = await prisma.flight.create({
        data: {
            flightNumber,
            airline: 'Mona Airways',
            ...airportCodesForRoute(route[0], route[1]),
            departureDate: new Date(Date.now() + hoursFromNow * HOUR),
            durationMinutes: 240,
            priceCents: 30_000,
            // All economy, so the seat numbers below are unambiguous: under the
            // default layout the low rows are premium cabins.
            firstClassRows: 0,
            businessRows: 0,
            premiumEconomyRows: 0,
            economyRows: 5,
            seatPattern: 'AB-CD',
        },
    });
    created.flightIds.push(flight.id);
    return flight;
}

async function bookFor(
    email: string,
    flightIds: number[],
    seatNumbers: string[],
    travellers: string[] = ['Ada'],
) {
    const user = await prisma.user.findUniqueOrThrow({ where: { email } });
    return bookHeldFlight(new FlightBookingService(), {
        flightIds,
        userId: user.id,
        passengers: travellers.map((firstName, index) => ({
            firstName,
            lastName: 'Lovelace',
            dateOfBirth: '1990-01-01',
            passportNumber: `C${suffix.slice(-6)}${index}`,
            gender: 'Female',
            // One seat per leg per traveller, offset so two travellers never
            // request the same seat on a leg.
            seatNumbers: seatNumbers.map(seat => `${seat[0]}${String.fromCharCode(seat.charCodeAt(1) + index)}`),
            cabinClass: 'ECONOMY' as const,
        })),
        idempotencyKey: randomUUID(),
    });
}

test.describe('Check-in journey', () => {
    test('checks in the leg whose window is open and leaves the return for later', async ({ page }) => {
        await createVerifiedAccount(page, { name: 'Check In', email: customerEmail, password });
        const outbound = await aFlight(`CI1-${suffix.slice(-6)}`, 5, ['Seattle, USA', 'Detroit, USA']);
        const inbound = await aFlight(
            `CI2-${suffix.slice(-6)}`,
            CHECK_IN_OPENS_HOURS + 72,
            ['Detroit, USA', 'Seattle, USA'],
        );
        await bookFor(customerEmail, [outbound.id, inbound.id], ['1A', '1A'], ['Ada', 'Grace']);

        await signInWithCredentials(page, { email: customerEmail, password });

        // The navigation entry is part of the acceptance criteria: check-in was
        // removed in #70 precisely because it led nowhere.
        await page.getByRole('link', { name: 'Check In' }).click();
        await expect(page).toHaveURL('/checkin');

        const outboundCard = page.getByRole('region', { name: /Departing: Seattle, USA to Detroit, USA/ });
        const returnCard = page.getByRole('region', { name: /Returning: Detroit, USA to Seattle, USA/ });
        await expect(outboundCard).toBeVisible();
        await expect(returnCard).toBeVisible();

        // The return is days from opening, so it must offer no control and say
        // why. One answer for the whole booking would get one of these wrong.
        // Exact: the card also carries "Check-in opens" and "Check-in closes"
        // labels, which a substring match resolves to as well.
        await expect(returnCard.getByText('Check-in not open yet', { exact: true })).toBeVisible();
        await expect(returnCard.getByRole('button', { name: /Check in/ })).toHaveCount(0);
        await expect(returnCard.getByText(/Check-in opens 24 hours before departure/)).toBeVisible();

        await expect(outboundCard.getByText('Check-in open', { exact: true })).toBeVisible();

        // The attestation gate. `docs/PASSENGER_DATA_POLICY.md` rules out showing
        // the details back or re-collecting them, so confirming is the only thing
        // check-in can honestly ask -- and it has to be asked before check-in.
        const attestation = outboundCard.getByRole('checkbox');
        await expect(attestation).not.toBeChecked();
        // The blocked label says what it wants rather than relying on a shade of
        // purple and an `aria-disabled` that only assistive tech can see.
        const submit = outboundCard.getByRole('button', { name: 'Confirm details to check in' });
        await expect(submit).toHaveAttribute('aria-disabled', 'true');

        // The way out is on screen before any mistake is made: the customer who
        // cannot honestly confirm never presses the button.
        await expect(outboundCard.getByText(/If any of them are wrong, contact us/))
            .toBeVisible();

        // Pressing it before confirming says why rather than doing nothing.
        //
        // `force` because Playwright honours `aria-disabled` and refuses to click,
        // which is itself worth knowing -- but a real mouse click on an
        // `aria-disabled` button that is not `disabled` does fire, so bypassing the
        // actionability check is what models the human rather than the tool.
        await submit.click({ force: true });
        await expect(outboundCard.getByRole('alert'))
            .toContainText('Confirm the traveller and document details');
        await expect(outboundCard.getByText('Check-in open', { exact: true })).toBeVisible();

        // The sentence names the categories and shows no values.
        await expect(outboundCard.getByText(/I confirm that each traveller/))
            .toContainText('passport details');

        await attestation.check();
        // Complying clears the refusal rather than leaving it under a live button.
        await expect(outboundCard.getByRole('alert')).toHaveCount(0);
        const ready = outboundCard.getByRole('button', { name: 'Check in 2 travellers' });
        await expect(ready).toHaveAttribute('aria-disabled', 'false');
        await ready.click();

        await expect(outboundCard.getByRole('status')).toContainText('Checked in for Mona Airways');
        // After the refresh the server is the one saying so, so this asserts the
        // stamp reached the database rather than only the browser's state.
        await expect(outboundCard.getByText('Checked in', { exact: true }).first()).toBeVisible();
        await expect(outboundCard.getByRole('button', { name: /Check in/ })).toHaveCount(0);
        // The return is untouched by the outbound's check-in.
        await expect(returnCard.getByText('Check-in not open yet', { exact: true })).toBeVisible();

        // And the attestation is not asked again anywhere on the page: a passport
        // does not change between the legs of one trip. It says so rather than
        // merely going quiet.
        await expect(page.getByRole('checkbox')).toHaveCount(0);
        await expect(outboundCard.getByText('Traveller and document details confirmed.'))
            .toBeVisible();
        const confirmed = await prisma.passenger.findMany({
            where: { booking: { user: { email: customerEmail } } },
            select: { documentsConfirmedAt: true },
        });
        expect(confirmed.length).toBeGreaterThan(0);
        expect(confirmed.every(passenger => passenger.documentsConfirmedAt !== null)).toBe(true);

        const stamps = await prisma.seatAssignment.findMany({
            where: { flightId: { in: [outbound.id, inbound.id] } },
            select: { flightId: true, checkedInAt: true },
        });
        expect(stamps.filter(seat => seat.flightId === outbound.id).every(seat => seat.checkedInAt !== null))
            .toBe(true);
        expect(stamps.filter(seat => seat.flightId === inbound.id).every(seat => seat.checkedInAt === null))
            .toBe(true);
    });

    test('shows another customer nothing of this booking', async ({ page }) => {
        await createVerifiedAccount(page, { name: 'Stranger', email: strangerEmail, password });
        await createVerifiedAccount(page, { name: 'Owner', email: otherOwnerEmail, password });
        const flight = await aFlight(`CI3-${suffix.slice(-6)}`, 5, ['Seattle, USA', 'Detroit, USA']);
        await bookFor(otherOwnerEmail, [flight.id], ['2A']);

        await signInWithCredentials(page, { email: strangerEmail, password });
        await page.goto('/checkin');

        // The query is scoped to the authenticated owner, so a stranger sees the
        // empty state rather than somebody else's confirmation reference.
        await expect(page.getByText(/no flights in the next month/)).toBeVisible();
        await expect(page.getByRole('region')).toHaveCount(0);
    });

    test('does not offer check-in to a visitor who is not signed in', async ({ page }) => {
        await page.goto('/checkin');

        await expect(page.getByRole('link', { name: 'log in' })).toBeVisible();
        await expect(page.getByRole('button', { name: /Check in/ })).toHaveCount(0);
    });
});

