  /// birth back to a customer and makes booking creation the only normal write
  /// path for them, so the only honest thing check-in can do is ask whether what
  /// was given at booking is right and record the answer (#77).
  ///
  /// A timestamp holds no identity data and reveals none, so unlike the columns
  /// above it is safe on a customer projection.
  ///
  /// Per traveller, not per leg: a passport does not change between the legs of
  /// one trip, so confirming it once covers the itinerary.
  documentsConfirmedAt    DateTime? @db.Timestamptz(3)

  bookingId Int
  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)

  /// Where this traveller sits: one per leg. A traveller is a person; a seat
  /// belongs to a flight, so the two are separate records (#137).
  seatAssignments SeatAssignment[]

  @@index([sensitiveDataExpiresAt])
}

  holderKey  String
  /// The migration writes `DEFAULT now()`, so the database supplies this. No
  /// production path calls `prisma.seatHold.create` -- the claim is one raw
  /// `INSERT ... ON CONFLICT` -- and the `expiresAt > createdAt` check would
  /// reject a row whose two times came from clocks that disagreed.
  createdAt  DateTime @default(now()) @db.Timestamptz(3)
  expiresAt  DateTime @db.Timestamptz(3)

  /// One live claim per seat. Expired rows stay in the table and are taken
  /// over in place, so this is unconditional rather than partial: a second row
  /// for the same seat should never exist even when the first is dead.
  @@unique([flightId, seatNumber])
  @@index([expiresAt])
  @@index([holderKey])
}

/// Where one traveller sits on one leg. Separated from Passenger because a
/// traveller is one person per booking while a seat is one per leg: a round trip
/// would otherwise need a second Passenger row, duplicating that person's
/// encrypted passport and date of birth along with their retention deadlines.
///
/// flightId is denormalised from the leg so that the seat-uniqueness constraint
/// can be expressed directly. A composite foreign key onto (id, flightId) of the
/// leg keeps the two in agreement.
model SeatAssignment {
  id          String       @id @default(cuid())
  passengerId String
  passenger   Passenger    @relation(fields: [passengerId], references: [id], onDelete: Cascade)
  legId       Int
  flightId    Int
  leg         ItineraryLeg @relation(fields: [legId, flightId], references: [id, flightId], onDelete: Cascade)
  flight      Flight       @relation(fields: [flightId], references: [id])
  seatNumber  String
  cabinClass  CabinClass
  /// When the seat was let go, and null while it is still held. Cancelling used
  /// to overwrite `seatNumber` instead, because the unique index could not tell
  /// a held seat from a released one and so held it forever (#76).
  releasedAt  DateTime?
  /// When this traveller checked in for this leg, and null until they do.
  ///
  /// Here rather than in a table of its own: this row is already "one traveller
  /// on one leg", which is precisely a check-in's key, and a seat change updates
  /// it in place so the check-in survives one. Check-in is per leg because the
  /// window is -- a round trip's return opens a day before the return flight
  /// (#77).
  ///
  /// Not constrained against `releasedAt`. Checking in and then cancelling sets
  /// both, and that is what happened; readers ask about a live seat instead.
  checkedInAt DateTime? @db.Timestamptz(3)

  /// A traveller sits in exactly one seat on any given leg.
  @@unique([passengerId, legId])
  /// The guard against two customers acquiring the same seat is a *partial*
  /// unique index on (flightId, seatNumber) WHERE "releasedAt" IS NULL, which
  /// Prisma cannot express and therefore does not manage. It is created in
  /// `20260810050000_release_seats_without_renaming`. Declaring the
  /// unconditional form here would recreate exactly the constraint that
  /// migration removes.
  @@index([flightId, releasedAt])
}

    // Ownership first, and against the booking rather than the leg: the leg is
    // then confirmed to belong to it, so naming somebody else's leg beside your
    // own booking cannot reach the update.
    const booking = await prisma.booking.findUnique({
        where: { id: bookingId },
        select: { userId: true },
    });
    if (!booking) throw new Error("Booking not found");
    if (booking.userId !== userId) throw new Error("Unauthorized");

    const refusal = await prisma.$transaction(async (tx) => {
        const leg = await tx.itineraryLeg.findFirst({
            where: { id: legId, bookingId, ...activeItineraryLegWhere },
            select: { flightId: true },
        });
        // A superseded leg lands here too. Its replacement is the one that can be
        // checked in, and it has its own id.
        if (!leg) throw new Error("Itinerary leg not found");

        // Serialises this against a concurrent cancellation, which locks every
        // flight on the booking in ascending id order. One lock cannot form a
        // cycle with an ordered set, so this adds no deadlock risk. Without it,
        // READ COMMITTED lets a cancellation commit between the read below and
        // the update, checking a traveller in on a booking that no longer exists
        // to be travelled (#76's reasoning, same hazard).
        await lockFlightForUpdate(tx, leg.flightId);

        // Re-read and re-decide under the lock. The page's answer was taken from
        // an unlocked read and staff can cancel the flight in between.
        const locked = await tx.itineraryLeg.findFirstOrThrow({
            where: { id: legId, bookingId, ...activeItineraryLegWhere },
            select: {
                booking: {
                    select: {
                        status: true,
                        // A timestamp only. No identity data is read here and
                        // none could be: that is what makes an attestation
                        // compatible with the policy at all.
                        passengers: { select: { documentsConfirmedAt: true } },
                    },
                },
                flight: { select: { departureDate: true, status: true } },
                seatAssignments: { select: { id: true, releasedAt: true, checkedInAt: true } },
            },
        });

        const eligibility = legCheckInEligibility({
            departsAt: locked.flight.departureDate,
            flightStatus: locked.flight.status,
            bookingStatus: locked.booking.status,
            seats: locked.seatAssignments,
        }, new Date());

        // Nothing left to do is success, not a refusal. Checked before the
        // window, or a party who checked in yesterday would be told the desk had
        // closed on them.
        if (eligibility.reason === 'ALREADY_CHECKED_IN') return null;
        if (!eligibility.allowed) return eligibility.reason;

        // The document attestation, which the policy makes the only thing
        // check-in can honestly ask. Read under the same lock as everything
        // else, and asked once per traveller rather than once per leg: a passport
        // does not change between an outbound and a return.
        const unconfirmed = locked.booking.passengers
            .filter(passenger => passenger.documentsConfirmedAt === null);
        if (unconfirmed.length > 0) {
            if (!documentsConfirmed) return 'DOCUMENTS_NOT_CONFIRMED';
            await tx.passenger.updateMany({
                // Only the ones who have not confirmed. Restamping would claim a
                // traveller attested later than they did, the same way
                // `checkedInAt` would.
                where: { bookingId, documentsConfirmedAt: null },
                data: { documentsConfirmedAt: new Date() },
            });
        }

        await tx.seatAssignment.updateMany({
            // Through `heldSeats` rather than restating the release condition
            // here: a released seat is nobody's boarding position, and the rule
            // that says so belongs in one place (#143). It also applies last, so
            // this caller cannot drop it. Naming the condition even in a comment
            // trips the guard that keeps it there, which is textual by design.
            //
            // `checkedInAt: null` keeps this idempotent and keeps the stamp
            // honest: a traveller who checked in an hour ago did not do so now.
            where: heldSeats({ legId, checkedInAt: null }),
            data: { checkedInAt: new Date() },
        });
        return null;
    });

    if (refusal === 'DOCUMENTS_NOT_CONFIRMED') {
        // Not a policy answer -- the window is open and the booking is fine. The
        // customer simply has not attested yet, which is an input contract.
        return actionValidationFailure(DOCUMENT_ATTESTATION_REQUIRED);
    }
    if (refusal) {
        // A policy answer, not a fault: the customer can act on the next step.
        return actionValidationFailure(checkInNextStep(refusal));
    }

    revalidatePath('/checkin');
    revalidatePath('/profile');
}

