export async function rebookItineraryAction(request: RebookItineraryRequest) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error('Unauthorized');

    const parsed = parseActionInput(rebookItineraryRequestSchema, request);
    if (!parsed.ok) return parsed;

    try {
        const result = await new ItineraryRebookingService().rebook({
            ...parsed.data,
            // Both values are server-owned. ownerUserId is rechecked after the
            // booking lock, while actorUserId records who resolved the disruption.
            ownerUserId: userId,
            actorUserId: userId,
        });
        revalidatePath('/profile');
        revalidatePath('/admin');
        return result;
    } catch (error) {
        if (error instanceof ItineraryRebookingError) {
            return actionValidationFailure(error.message);
        }
        throw error;
    }
}

export async function changeBookingSeatsAction(
    bookingId: number,
    seatChanges: { passengerId: string, legId: number, seatNumber: string }[]
) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error("Unauthorized");
    const parsed = parseActionInput(seatChangesSchema, { bookingId, seatChanges });
    if (!parsed.ok) return parsed;
    bookingId = parsed.data.bookingId;
    seatChanges = parsed.data.seatChanges;

    const booking = await prisma.booking.findUnique({
        where: { id: bookingId },
        include: {
            legs: {
                where: activeItineraryLegWhere,
                include: { flight: true },
                orderBy: { sequence: 'asc' },
            },
        }
    });
    if (!booking) throw new Error("Booking not found");

    if (!hasVerifiedStaffAccess(session) && booking.userId !== userId) {
        throw new Error("Unauthorized");
    }

    // A seat belongs to a leg, so each change names one. Legs are resolved from
    // the booking rather than trusted from the client: a leg id from another
    // booking would otherwise move a stranger's seat.
    const legsById = new Map(booking.legs.map(leg => [leg.id, leg]));

    // A seat on a flight the airline cancelled is not a seat to move. The
    // profile keeps "Change Seats" on a disrupted round trip because the other
    // leg may still be flown, so the guard has to be per leg and it has to be
    // here rather than in the component (#76).
    const grounded = seatChanges
        .map(change => legsById.get(change.legId))
        .filter(leg => leg?.flight?.status === 'CANCELLED');
    if (grounded.length > 0) {
        return actionValidationFailure(
            'That flight has been cancelled by the airline, so its seats cannot be changed. '
            + 'Cancel the booking for a full refund instead.'
        );
    }
    for (const change of seatChanges) {
        if (!legsById.has(change.legId)) {
            throw new Error(`Leg ${change.legId} does not belong to booking ${bookingId}`);
        }
    }

    // Lock in ascending flight id, matching FlightBookingService, so two
    // requests touching the same pair of flights cannot deadlock.
    const flightIds = [...new Set(
        seatChanges.map(change => legsById.get(change.legId)!.flightId)
    )].sort((left, right) => left - right);

    // Execute inside transaction to prevent concurrent seat collisions
    await prisma.$transaction(async (tx) => {
        for (const flightId of flightIds) {
            await lockFlightForUpdate(tx, flightId);
        }
        const lockedBooking = await tx.booking.findUnique({
            where: { id: bookingId },
            select: {
                status: true,
                passengers: { select: { id: true } },
            }
        });
        if (!lockedBooking) throw new Error("Booking not found");
        if (lockedBooking.status === "CANCELLED") {
            throw new Error("Seats cannot be changed on a cancelled booking");
        }

        // The cabin a seat has to fit is the one held on that leg, which is
        // recorded with the assignment. The traveller row used to carry a
        // single cabin describing the outbound, so a leg booked in a different
        // cabin was checked against the wrong one (#137).
        const heldCabins = new Map(
            (await tx.seatAssignment.findMany({
                where: { legId: { in: seatChanges.map(change => change.legId) } },
                select: { passengerId: true, legId: true, cabinClass: true },
            })).map(seat => [`${seat.legId}:${seat.passengerId}`, seat.cabinClass])
        );

        const lockedFlights = new Map(
            (await tx.flight.findMany({ where: { id: { in: flightIds } } }))
                .map(flight => [flight.id, flight])
        );
        if (lockedFlights.size !== flightIds.length) throw new Error("Flight not found");

        for (const change of seatChanges) {
            const passenger = lockedBooking.passengers.find(p => p.id === change.passengerId);
            if (!passenger) {
                throw new Error(`Passenger ${change.passengerId} does not belong to booking ${bookingId}`);
            }
            const cabinClass = heldCabins.get(`${change.legId}:${change.passengerId}`);
            if (!cabinClass) {
                throw new Error(`Passenger ${change.passengerId} holds no seat on leg ${change.legId}`);
            }
            const flightId = legsById.get(change.legId)!.flightId;
            assertSeatAvailableForCabin(change.seatNumber, cabinClass, lockedFlights.get(flightId)!);
        }

        // Occupancy comes from the seat assignments, which record a seat per
        // leg. Reading Passenger.seatNumber would report the outbound seat for
        // every leg of a round trip.
        const occupied = await tx.seatAssignment.findMany({
            where: heldSeats({
                flightId: { in: flightIds },
                NOT: { leg: { bookingId } },
            }),
            select: { flightId: true, seatNumber: true },
        });
        const occupiedSeats = new Set(occupied.map(seat => `${seat.flightId}:${seat.seatNumber}`));

        for (const change of seatChanges) {
            const flightId = legsById.get(change.legId)!.flightId;
            if (occupiedSeats.has(`${flightId}:${change.seatNumber}`)) {
                throw new Error(`Seat ${change.seatNumber} is already occupied by another passenger.`);
            }
        }

        // Apply changes. Scoped to the named leg: a passenger on a round trip
        // has an assignment per leg, so updating by passenger alone would
        // overwrite the seat they still hold on the other one.
        for (const change of seatChanges) {
            await tx.seatAssignment.updateMany({
                where: { passengerId: change.passengerId, legId: change.legId },
                data: { seatNumber: change.seatNumber }
            });
        }
    });

    revalidatePath('/profile');
    revalidatePath('/admin');
}

export async function deleteReviewAction(reviewId: string) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error("Unauthorized");

    const parsed = parseActionInput(stringIdSchema, reviewId);
    if (!parsed.ok) return parsed;
    reviewId = parsed.data;
    const review = await prisma.review.findUnique({
        where: { id: reviewId }
    });
    if (!review) throw new Error("Review not found");

    if (!hasVerifiedStaffAccess(session) && review.userId !== userId) {
        throw new Error("Unauthorized");
    }

    const deleted = await prisma.review.delete({
    };

    const handleRetryRefund = (bookingId: number, amountCents: number) => {
        setActiveRefundBookingId(bookingId);
        setRefundFeedback({
            bookingId,
            message: `Retrying your ${formatPrice(amountCents)} refund.`,
            focus: false,
        });
        startTransition(async () => {
            try {
                const result = await retryBookingRefundAction(bookingId);
                if (isActionValidationFailure(result)) {
                    alert(result.error.message);
                    setRefundFeedback(null);
                    return;
                }
                const message = result.status === 'SUCCEEDED'
                    ? `${formatPrice(amountCents)} refund sent.`
                    : result.status === 'PENDING'
                        ? `${formatPrice(amountCents)} refund is pending.`
                        : `${formatPrice(amountCents)} refund needs attention.`;
                setRefundFeedback({ bookingId, message, focus: true });
                router.refresh();
            } catch {
                setRefundFeedback(null);
                alert('Your refund is still pending. Please try again later.');
            } finally {
                setActiveRefundBookingId(null);
            }
        });
    };

    const handleDeleteReview = (reviewId: string) => {
        if (!confirm('Are you sure you want to delete this review?')) return;

        startTransition(async () => {
            try {
                const result = await deleteReviewAction(reviewId);
                if (isActionValidationFailure(result)) throw new Error(result.error.message);
                router.refresh();
            } catch (error) {
                alert('Failed to delete review. Please try again.');
            }
        });
    };

    const handleUnfavorite = (cityId: number, cityName: string) => {
        startTransition(async () => {
            try {
                const result = await toggleFavoriteCityGuideAction(cityId);
                if (isActionValidationFailure(result)) throw new Error(result.error.message);
                router.refresh();
            } catch (error) {
                alert('Failed to update favorite. Please try again.');
            }
        });
    };

    const handleSaveSeats = async () => {
        if (!selectedBooking) return;

        for (const leg of modalLegs) {
            for (const p of selectedBooking.passengers) {
                if (!passengerSeats[seatKey(leg.id, p.id)]) {
                    const which = modalLegs.length > 1
                        ? ` on the ${leg.id === modalLegs[0].id ? 'departing' : 'returning'} flight`
                        : '';
                    setModalError(`Please select a seat for ${p.firstName} ${p.lastName}${which}`);
                    setActiveLegIdx(modalLegs.indexOf(leg));
                    return;
                }
            }
        }

        setIsSavingSeats(true);
        setModalError(null);

        try {
            const seatChanges = modalLegs.flatMap(leg =>
                selectedBooking.passengers.map(p => ({
                    passengerId: p.id,
                    legId: leg.id,
                    seatNumber: passengerSeats[seatKey(leg.id, p.id)]
                }))
            );

            const result = await changeBookingSeatsAction(selectedBooking.id, seatChanges);
            if (isActionValidationFailure(result)) {
                setModalError(result.error.message);
                return;
            }
            setSelectedBooking(null);
            router.refresh();
        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : 'Failed to update seats. Please try again.';
            setModalError(msg);
        } finally {
            setIsSavingSeats(false);
        }
    };

    const getRowsForClass = (cabinClass: string) => {
        const flight = activeLeg?.flight ?? null;
        const firstClassCount = flight?.firstClassRows !== undefined && flight?.firstClassRows !== null ? Number(flight.firstClassRows) : 3;
        const businessCount = flight?.businessRows !== undefined && flight?.businessRows !== null ? Number(flight.businessRows) : 3;
        const premiumEconomyCount = flight?.premiumEconomyRows !== undefined && flight?.premiumEconomyRows !== null ? Number(flight.premiumEconomyRows) : 4;
        const economyCount = flight?.economyRows !== undefined && flight?.economyRows !== null ? Number(flight.economyRows) : 20;

        let currentOffset = 1;

        if (cabinClass === 'FIRST') {
            return Array.from({ length: firstClassCount }, (_, i) => currentOffset + i);
        }
        currentOffset += firstClassCount;

        if (cabinClass === 'BUSINESS') {
            return Array.from({ length: businessCount }, (_, i) => currentOffset + i);
        }
        currentOffset += businessCount;

        if (cabinClass === 'PREMIUM_ECONOMY') {
            return Array.from({ length: premiumEconomyCount }, (_, i) => currentOffset + i);
        }
        currentOffset += premiumEconomyCount;

        if (cabinClass === 'ECONOMY') {
            return Array.from({ length: economyCount }, (_, i) => currentOffset + i);
        }
        return Array.from({ length: economyCount }, (_, i) => currentOffset + i);
    };

    const isSeatOccupied = (seat: string) => {
        if (!selectedBooking || !activeLeg) return false;
        const activePassenger = selectedBooking.passengers[activePassengerIdx];

        // Seats the other travellers on this booking hold on this leg.
        const selectedByOthers = selectedBooking.passengers
            .filter(p => p.id !== activePassenger?.id)
            .map(p => seatFor(p.id));

        // This booking's own seats on this leg are not obstacles to itself.
        const ownSeatsOnLeg = selectedBooking.passengers.map(p =>
            activeLeg.seatAssignments?.find(s => s.passengerId === p.id)?.seatNumber
        );
        const occupiedByOthersOnFlight = (modalOccupiedSeats[activeLeg.id] ?? []).filter(
            s => !ownSeatsOnLeg.includes(s)
        );

        return occupiedByOthersOnFlight.includes(seat) || selectedByOthers.includes(seat);
    };

    return (
        <div className="page-container profile">
            <div className="sidebar-menu">
                <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
                    {/* OAuth providers may supply arbitrary remote or data URLs
                        that cannot be enumerated in Next Image configuration. */}
