            ? `${formatPrice(refund.amountCents)} refund sent.`
            : refund.status === 'PENDING'
                ? `${formatPrice(refund.amountCents)} refund is pending.`
                : `${formatPrice(refund.amountCents)} refund needs attention.`
        : null;

