import type { Prisma } from '@prisma/client';

type FlightLockClient = Pick<Prisma.TransactionClient, '$queryRaw'>;

export async function lockFlightForUpdate(tx: FlightLockClient, flightId: number): Promise<void> {
    await tx.$queryRaw`SELECT "id" FROM "Flight" WHERE "id" = ${flightId} FOR UPDATE`;
}

export async function lockBookingForUpdate(
    tx: FlightLockClient,
    bookingId: number,
): Promise<void> {
    await tx.$queryRaw`SELECT "id" FROM "Booking" WHERE "id" = ${bookingId} FOR UPDATE`;
}

/**
 * Locks the bookings touching a flight, so two staff transactions changing two
 * legs of one itinerary cannot both decide its status from a stale snapshot.
 *
 * Locking the flight is not enough. `updateFlightStatusAction` decides each
 * booking's new status by reading the statuses of *other* flights -- the other
 * legs -- and those rows belong to flights this transaction does not hold. Under
 * READ COMMITTED two concurrent changes each read the other's pre-image, and
 * both are wrong: cancelling one leg while reinstating another left the booking
 * CONFIRMED on a cancelled flight, and reinstating both at once left it
 * DISRUPTED while both flights operated (#76).
 *
 * The booking row is what they have in common, so it is what serialises them.
 * Ascending id, matching every other lock order in this application, so two
 * transactions holding overlapping sets cannot form a cycle. Once the second
 * transaction is through the lock its next statement takes a fresh snapshot and
 * sees the first one's committed work.
 */
export async function lockBookingsOnFlightForUpdate(
    tx: FlightLockClient,
    flightId: number,
): Promise<number[]> {
    const locked = await tx.$queryRaw<Array<{ id: number }>>`
        SELECT b."id"
        FROM "Booking" b
        WHERE EXISTS (
            SELECT 1 FROM "ItineraryLeg" l
            WHERE l."bookingId" = b."id"
              AND l."flightId" = ${flightId}
              AND l."supersededAt" IS NULL
        )
        AND b."status" <> 'CANCELLED'
        ORDER BY b."id"
        FOR UPDATE
    `;
    return locked.map(row => row.id);
}
const DEPARTED_MESSAGE =
    'This booking cannot be cancelled because the flight has already departed.';

/**
 * Thrown from inside the cancellation transaction so it rolls back, and turned
 * into the same refusal the early check gives. A policy answer rather than a
 * fault, but it has to unwind the transaction to be one.
 */
class BookingDepartedError extends Error {}

/**
 * Check one leg of one booking in, for everybody travelling on it.
 *
 * A leg at a time because the window is per leg: a round trip's return opens a
 * day before the return flight, long after the outbound has flown. Everybody at
 * once because the booking's owner is acting for their own party, and a control
 * per traveller buys nothing until there is something that differs between them
 * -- travel documents (#77) are where that starts.
 *
 * Scoped strictly to the owner, with no staff path. `hasVerifiedStaffAccess`
 * would be the wrong shape here: checking a customer in on their behalf is a
 * support workflow with its own audit requirements (#86), not a widening of
 * this action.
 *
 * Idempotent. Pressing it twice, or once for a party already checked in, stamps
 * nothing further and reports success -- so the closed-window refusal below
 * cannot fire at a customer who is already checked in and has nothing to fix.
 */
export async function checkInLegAction(input: {
    bookingId: number;
    legId: number;
    documentsConfirmed?: boolean;
}) {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (!userId) throw new Error("Unauthorized");

    const parsed = parseActionInput(checkInRequestSchema, input);
    if (!parsed.ok) return parsed;
    const { bookingId, legId, documentsConfirmed } = parsed.data;

    // Ownership first, and against the booking rather than the leg: the leg is
    // then confirmed to belong to it, so naming somebody else's leg beside your
    // own booking cannot reach the update.
    const booking = await prisma.booking.findUnique({
        where: { id: bookingId },
        select: { userId: true },
    });
    if (!booking) throw new Error("Booking not found");
    if (booking.userId !== userId) throw new Error("Unauthorized");

    const refusal = await prisma.$transaction(async (tx) => {
        const leg = await tx.itineraryLeg.findFirst({
            where: { id: legId, bookingId, ...activeItineraryLegWhere },
            select: { flightId: true },
