for (const change of seatChanges) {
    if (!legsById.has(change.legId)) {
        throw new Error(`Leg ${change.legId} does not belong to booking ${bookingId}`);
    }
}

// Lock in ascending flight id, matching FlightBookingService, so two
// requests touching the same pair of flights cannot deadlock.
const flightIds = [...new Set(
    seatChanges.map(change => legsById.get(change.legId)!.flightId)
)].sort((left, right) => left - right);

class CheckedInSeatChangeError extends Error {}

try {
    // Execute inside transaction to prevent concurrent seat collisions.
    // The same flight lock serialises this with check-in: if check-in wins,
    // the read below sees its stamp and refuses; if this wins, check-in later
    // stamps the new seat. No issued boarding pass can silently become stale.
    await prisma.$transaction(async (tx) => {
        for (const flightId of flightIds) {
            await lockFlightForUpdate(tx, flightId);
        }
        const lockedBooking = await tx.booking.findUnique({
            where: { id: bookingId },
            select: {
                status: true,
                passengers: { select: { id: true } },
            }
        });
        if (!lockedBooking) throw new Error("Booking not found");
        if (lockedBooking.status === "CANCELLED") {
            throw new Error("Seats cannot be changed on a cancelled booking");
        }

    // The cabin a seat has to fit is the one held on that leg, which is
    // recorded with the assignment. The traveller row used to carry a
    // single cabin describing the outbound, so a leg booked in a different
    // cabin was checked against the wrong one (#137).
        const heldAssignments = new Map(
            (await tx.seatAssignment.findMany({
                where: { legId: { in: seatChanges.map(change => change.legId) } },
                select: {
                    passengerId: true,
                    legId: true,
                    cabinClass: true,
                    checkedInAt: true,
                },
            })).map(seat => [`${seat.legId}:${seat.passengerId}`, seat])
        );

        const lockedFlights = new Map(
            (await tx.flight.findMany({ where: { id: { in: flightIds } } }))
                .map(flight => [flight.id, flight])
        );
        if (lockedFlights.size !== flightIds.length) throw new Error("Flight not found");

        for (const change of seatChanges) {
            const passenger = lockedBooking.passengers.find(p => p.id === change.passengerId);
            if (!passenger) {
                throw new Error(`Passenger ${change.passengerId} does not belong to booking ${bookingId}`);
            }
            const heldAssignment = heldAssignments.get(`${change.legId}:${change.passengerId}`);
            if (!heldAssignment) {
                throw new Error(`Passenger ${change.passengerId} holds no seat on leg ${change.legId}`);
            }
            if (heldAssignment.checkedInAt) {
                throw new CheckedInSeatChangeError(
                    'Seats cannot be changed once you have checked in. '
                    + 'Use the seat shown on your boarding pass.'
                );
            }
            const flightId = legsById.get(change.legId)!.flightId;
            assertSeatAvailableForCabin(
                change.seatNumber,
                heldAssignment.cabinClass,
                lockedFlights.get(flightId)!,
            );
        }

    // Occupancy comes from the seat assignments, which record a seat per
    // leg. Reading Passenger.seatNumber would report the outbound seat for
    // every leg of a round trip.
        const occupied = await tx.seatAssignment.findMany({
            where: heldSeats({
                flightId: { in: flightIds },
                NOT: { leg: { bookingId } },
            }),
            select: { flightId: true, seatNumber: true },
        });
        const occupiedSeats = new Set(occupied.map(seat => `${seat.flightId}:${seat.seatNumber}`));

        for (const change of seatChanges) {
            const flightId = legsById.get(change.legId)!.flightId;
            if (occupiedSeats.has(`${flightId}:${change.seatNumber}`)) {
                throw new Error(`Seat ${change.seatNumber} is already occupied by another passenger.`);
            }
        }

    // Apply changes. Scoped to the named leg: a passenger on a round trip
    // has an assignment per leg, so updating by passenger alone would
    // overwrite the seat they still hold on the other one.
        for (const change of seatChanges) {
            await tx.seatAssignment.updateMany({
                where: { passengerId: change.passengerId, legId: change.legId },
                data: { seatNumber: change.seatNumber }
            });
        }
    });
} catch (error) {
    if (error instanceof CheckedInSeatChangeError) {
            focus: 'message',
        });
        router.refresh();
    } catch (error) {
        // Logged as well as shown. Every genuine server fault -- a superseded
        // leg, a transaction timeout while a cancellation holds the flight
        // lock, a dropped connection -- reaches the customer as the same
        // sentence, so without this there is nothing anywhere to tell a real
        // fault from a transient one. `titlebar.tsx` logs its equivalent.
        console.error('Failed to check in:', error);
        setFeedback({
            legId: leg.legId,
            kind: 'error',
            message: 'Could not check you in. Please try again.',
            focus: 'message',
        });
    } finally {
        setPendingLegId(null);
    }
};

return (
    <div className="page-container checkin">
        <div className="checkin-shell">
            <h1>Check in</h1>
            {/* Both numbers come from the policy. Written out as prose they
                went on claiming 24 hours after the constant moved, with
                nothing failing -- every other mention on this page is
                derived. */}
            <p className="checkin-intro">
                Check-in opens {CHECK_IN_OPENS_HOURS} hours before each flight
                leaves and closes {CHECK_IN_CLOSES_MINUTES} minutes before it.
                A trip with more than one flight is checked in one flight at a
                time.
            </p>

            {legs.length === 0 ? (
                <p className="checkin-empty">
                    You have no flights in the next month.{' '}
                    <Link href="/book">Book a flight</Link> to travel with us.
                </p>
            ) : (
                <ul className="checkin-leg-list">
                    {legs.map((leg) => {
                        const busy = pendingLegId === leg.legId;
                        const shown = feedback?.legId === leg.legId ? feedback : null;
                        const headingId = `checkin-leg-${leg.legId}-heading`;

                        return (
                            <li key={leg.legId}>
                                <section
                                    className="checkin-card"
                                    aria-labelledby={headingId}
                                >
                                    <div className="checkin-card-head">
                                        <h2 id={headingId}>
                                            {/* Empty for a booking with one
                                                leg, which is not "Departing"
                                                as opposed to anything. Three
                                                interleaved bookings read as
                                                "Departing / Departing /
                                                Returning" otherwise, which
                                                looks like one itinerary. */}
                                            {leg.directionLabel && `${leg.directionLabel}: `}
                                            {leg.from} to {leg.to}
                                        </h2>
                                        {/* The state is text, not a colour.
                                            A badge distinguished only by hue
                                            says nothing to a screen reader
                                            and nothing to anyone who cannot
                                            separate the two hues. */}
                                        <p
                                            className={`checkin-state checkin-state-${leg.reason.toLowerCase().replaceAll('_', '-')}`}
                                        >
                                            {leg.statusLabel}
                                        </p>
                                    </div>

                                    <dl className="checkin-facts">
                                        <div>
                                            <dt>Flight</dt>
                                                                        maxWidth: '14rem',
                                                                    }}
                                                                >
                                                                    {refundText}
                                                                </p>
                                                            )}
                                                            {hasCheckedInLeg && (
                                                                <p style={{
                                                                    margin: '4px 0 0',
                                                                    fontSize: '0.75rem',
                                                                    color: 'rgba(255,255,255,0.82)',
                                                                    maxWidth: '14rem',
                                                                }}>
                                                                    Seats are fixed after check-in.
                                                                </p>
                                                            )}
                                                        </td>
                                                        <td className="py-2 text-right align-top booking-actions-cell" rowSpan={legRows.length}>
                                                            {(cancellable || refundRetryable) && (
                                                                <div className="booking-actions">
                                                                    {canChangeSeats && (
                                                                        <button
                                                                            onClick={() => setSelectedBooking(booking)}
                                                                            disabled={isPending}
                                                                            style={{
                                                                                backgroundColor: '#8b5cf6', color: 'white', borderRadius: '4px',
                                                                                height: 'auto', width: 'auto', cursor: 'pointer', whiteSpace: 'nowrap'
                                                                            }}
                                                                        >
                                                                            Change Seats
                                                                        </button>
                                                                    )}
                                                                    {cancellable && (
                                                                        <>
                                                                            <button
                                                                                onClick={() => handleCancelBooking(booking.id, cancelledLeg?.flight?.flightNumber || '', isDisrupted)}
                                                                                disabled={isPending}
                                                                                style={{
                                                                                    backgroundColor: '#ef4444', color: 'white', borderRadius: '4px',
                                                                                    height: 'auto', width: 'auto', cursor: 'pointer'
                                                                                }}
                                                                            >
                                                                                Cancel
                                                                            </button>
                                                                        </>
                                                                    )}
                                                                    {refundRetryable && (
                                                                        <button
                                                                            onClick={() => handleRetryRefund(booking.id, refundAmountCents!)}
