describe('Round-trip bookings', () => {
    const roundTripBooking = {
        ...sampleBookings[0],
        id: 202,
        reference: 'MA-22222222222222222222',
        totalPriceCents: 66000,
        legs: [
            {
                id: 501,
                sequence: 1,
                flight: {
                    id: 201,
                    flightNumber: 'GA101',
                    airline: 'Gemini Airways',
                    from: 'Seattle, USA',
                    to: 'Detroit, USA',
                    departureDate: '2026-06-15T08:00:00Z',
                    returnDate: null,
                    priceCents: 35000,
                },
                seatAssignments: [{ passengerId: 'p-1', seatNumber: '12A' }],
            },
            {
                id: 502,
                sequence: 2,
                flight: {
                    id: 202,
                    flightNumber: 'GA900',
                    airline: 'Gemini Airways',
                    from: 'Detroit, USA',
                    to: 'Seattle, USA',
                    departureDate: '2026-06-22T17:00:00Z',
                    returnDate: null,
                    priceCents: 31000,
                },
                seatAssignments: [{ passengerId: 'p-1', seatNumber: '4C' }],
            },
        ],
    };

    const profile = (
        bookings: unknown[],
        replacementOptions: Record<number, ReplacementFlightGroup[]> = {},
        accountTimeZone = 'UTC',
    ) => (
        <ProfileClient
            userName="Jane Doe"
            userAvatar="avatar.png"
            accountTimeZone={accountTimeZone}
            accountTimeZoneChoices={['UTC', 'America/Los_Angeles']}
            currentStatus="Gold"
            currentPoints={4200}
            bookings={bookings as never}
            favorites={[]}
            reviews={[]}
            activityData={[]}
            monthlyHistory={[]}
            renderedAt={new Date('2026-06-01T00:00:00Z').getTime()}
            replacementOptions={replacementOptions}
        />
    );
    const renderBookings = (
        bookings: unknown[],
        replacementOptions: Record<number, ReplacementFlightGroup[]> = {},
        accountTimeZone = 'UTC',
    ) => render(profile(bookings, replacementOptions, accountTimeZone));

    it('labels account activity and history with the saved timezone', () => {
        renderBookings([], {}, 'America/Los_Angeles');

        expect(screen.getByRole('columnheader', {
            name: 'Activity time (America/Los_Angeles)',
        })).toBeInTheDocument();
        })).toBeInTheDocument();
        expect(screen.getByTestId('history-chart'))
            .toHaveAttribute('data-time-zone', 'America/Los_Angeles');
    });

    it('lists every leg of the itinerary, in order', () => {
        renderBookings([roundTripBooking]);

        const row = screen.getByTestId('booking-row-202');
        expect(row).toHaveTextContent('Gemini Airways GA101');
        expect(row).toHaveTextContent('Gemini Airways GA900');
        expect(row).toHaveTextContent('Seattle, USA → Detroit, USA');
        expect(row).toHaveTextContent('Detroit, USA → Seattle, USA');

        // Order follows the itinerary, not the order rows happen to arrive.
        const legs = within(row).getAllByTestId(/^booking-leg-/);
        expect(legs).toHaveLength(2);
        expect(legs[0]).toHaveTextContent('GA101');
        expect(legs[1]).toHaveTextContent('GA900');
    });

    it('labels the booking instant in the saved timezone once for every itinerary', () => {
